import re

with open('doc/superhero.md', 'r') as f:
    content = f.read()

lines = content.split('\n')

superhero_data = {}  # superhero_id -> {'height': float, 'publisher_id': int}

current_id = None
for i, line in enumerate(lines):
    # Look for ID mentions
    id_match = re.search(r'(?:registration is tracked with the identifier|registered under ID|cataloged under reference code|identified by registry number|listed at ID)\s+(\d+)', line, re.IGNORECASE)
    if id_match:
        current_id = int(id_match.group(1))

    # Look for height - try multiple patterns
    height_match = re.search(r'(?:standard|recorded|listed)\s+height(?:\s+is)?\s+([\d.]+)\s*centimeters', line, re.IGNORECASE)
    if height_match and current_id:
        h = float(height_match.group(1))
        if h > 0:
            if current_id not in superhero_data:
                superhero_data[current_id] = {}
            superhero_data[current_id]['height'] = h

    # Also try 'height is X centimeters' pattern
    height_match2 = re.search(r'height is\s+(?:recorded as |listed as )?([\d.]+)\s*centimeters', line, re.IGNORECASE)
    if height_match2 and current_id:
        h = float(height_match2.group(1))
        if h > 0:
            if current_id not in superhero_data:
                superhero_data[current_id] = {}
            superhero_data[current_id]['height'] = h

    # Look for publisher affiliation
    pub_match = re.search(r'publisher affiliation is (?:recorded as|logged with the code)\s+(\d+)', line, re.IGNORECASE)
    if pub_match and current_id:
        pub_id = int(pub_match.group(1))
        if current_id not in superhero_data:
            superhero_data[current_id] = {}
        superhero_data[current_id]['publisher_id'] = pub_id

print(f"Total superheroes parsed: {len(superhero_data)}")
print(f"Superheroes with height: {sum(1 for d in superhero_data.values() if 'height' in d)}")
print(f"Superheroes with publisher: {sum(1 for d in superhero_data.values() if 'publisher_id' in d)}")

# Sample some data
print("\nSample entries:")
for sid in sorted(list(superhero_data.keys()))[:10]:
    data = superhero_data[sid]
    print(f"ID {sid}: {data}")

